INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17101, 'Isaiah 29:19', 'Isaiah', 29, 19, '&nbsp;عاجزان به بيا د مالِک خُدائ ورکړے شوې خوشحالۍ نه په جامو کښې نۀ ځائيږى، او غريبانان به د بنى اِسرائيل د مقدس ذات خوشحالى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17102, 'Isaiah 29:20', 'Isaiah', 29, 20, '&nbsp;ظالمان به باقى پاتې نۀ شى، مغروره به ختم شى او څوک چې د بدو منصوبه جوړوى هغوئ به قتل کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17103, 'Isaiah 29:21', 'Isaiah', 29, 21, '&nbsp;خُدائ پاک به هغه خلق تباه کړى چې څوک د دروغو ګواهى کوى، هغه خلق چې قاضيان د غلطو فېصلو کولو دپاره دوکه کوى، هغه خلق چې څوک دروغ وائى د دې دپاره چې بې‌ګناه خلقو ته اِنصاف مِلاو نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17104, 'Isaiah 29:22', 'Isaiah', 29, 22, '&nbsp;نو ځکه مالِک خُدائ د يعقوب د اولاد خُدائ پاک، چا چې اِبراهيم د مصيبت نه خلاص کړو، داسې فرمائى، ”زما د خلقو به نوره بې‌عزتى نۀ کيږى او د هغوئ رنګونه به د شرم په وجه نور زېړ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17105, 'Isaiah 29:23', 'Isaiah', 29, 23, '&nbsp;کله چې تاسو هغه بچى ووينئ چې زۀ تاسو له درکوم، نو تاسو ته به بيا پته ولګى چې زۀ د بنى اِسرائيلو مقدس ذات يم. تاسو به زما درناوى کوئ او د يعقوب د خُدائ پاک رُعب به منئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17106, 'Isaiah 29:24', 'Isaiah', 29, 24, '&nbsp;بدعمله خلق به پوهه حاصله کړى او هغه خلق چې کوم هر وخت فريادونه کوى نو هغوئ به اصُول ومنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17107, 'Isaiah 30:1', 'Isaiah', 30, 1, '&nbsp;مالِک خُدائ فرمائيلى دى، ”اے باغيانو بچو په تاسو افسوس. ځکه چې تاسو په هغه منصوبو باندې کار کوئ چې کومې زما نۀ دى، او زما د مرضۍ خِلاف معاهدې کوئ او تاسو ګناهونو پسې ګناهونه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17108, 'Isaiah 30:2', 'Isaiah', 30, 2, '&nbsp;تاسو زما د مشورې نه بغېر د مدد دپاره مِصر ته لاړئ. تاسو غوښتل چې مِصريان مو بچ کړى، نو په دې وجه تاسو د مِصر په فِرعون باندې يقين وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17109, 'Isaiah 30:3', 'Isaiah', 30, 3, '&nbsp;خو په فِرعون باندې اعتماد سره به تاسو رسوا شئ او په هغۀ باندې بهروسۍ سره به تاسو بې‌عزته شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17110, 'Isaiah 30:4', 'Isaiah', 30, 4, '&nbsp;اګر چې د هغۀ آفسران ضُعن کښې دى او د هغۀ سفيران حنيس ته رسېدلى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17111, 'Isaiah 30:5', 'Isaiah', 30, 5, '&nbsp;هغه ټول چې په هغۀ بهروسه کوى هغوئ به وشرميږى. او هغه به ستاسو مدد نۀ کوى بلکې په ځائ د دې به ستاسو بې‌عزتى وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17112, 'Isaiah 30:6', 'Isaiah', 30, 6, '&nbsp;د جنوبى صحرا د ځناورو په حقله د خُدائ پاک پېغام دا دے، هغه سفيران به په داسې خطرناک مُلک کښې سفر کوى، چرته چې ازمرى اوسيږى او چرته چې تور ماران او نور زهرژن ماران دى. هغوئ د يو داسې قوم دپاره خپل خرونه او اوښان د قيمتى تُحفو نه بار کړى دى څوک چې د دوئ هيڅ مدد نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17113, 'Isaiah 30:7', 'Isaiah', 30, 7, '&nbsp;د مِصر نه چې کوم مدد ملاويږى نو هغه بې‌فائدې دے. نو ځکه ما په مِصر باندې يو بل نوم ”بې‌ضرره اژدها“ اېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17114, 'Isaiah 30:8', 'Isaiah', 30, 8, '&nbsp;اوس لاړ شه او دا الفاظ په يو کِتاب کښې وليکه. چې دا د راروانو وختونو دپاره د تل دپاره يوه ګواهى شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17115, 'Isaiah 30:9', 'Isaiah', 30, 9, '&nbsp;ځکه چې دا قوم سرکش دے او دا همېشه دروغ وائى او د مالِک خُدائ تعليمات منلو ته تيار نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17116, 'Isaiah 30:10', 'Isaiah', 30, 10, '&nbsp;هغوئ رويا کتونکو ته وائى چې، ”تاسو روياګانې مۀ وينئ،“ پېغمبرانو ته وائى، ”مونږ ته د هغه څۀ په حقله خبرې مۀ کوئ چې څۀ حقيقت وى. مونږ ته د خوند خبرې کوئ، خېر دے کۀ هغه دروغ هم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17117, 'Isaiah 30:11', 'Isaiah', 30, 11, '&nbsp;زمونږ د لارې نه اخوا شئ او زمونږ مخه مۀ نيسئ. مونږ ستاسو د بنى اِسرائيلو د مقدس ذات په حقله اورېدل نۀ غواړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17118, 'Isaiah 30:12', 'Isaiah', 30, 12, '&nbsp;ځکه خو د بنى اِسرائيلو مقدس ذات داسې فرمائى، ”زۀ چې څۀ درته وايم نو تاسو هغه رد کړئ او د ظلم زياتى او دوکې نه کار اخلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17119, 'Isaiah 30:13', 'Isaiah', 30, 13, '&nbsp;دا ګناه به ستاسو دپاره د يو داسې اوچت دېوال په شان وى چې چاودے او کوږوالے پکښې راغلے وى او دېوال کينوى او بيا سمدستى يو درز سره زمکې ته راګزار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17120, 'Isaiah 30:14', 'Isaiah', 30, 14, '&nbsp;دا ټوټې ټوټې شى د خټې د هغه لوښى په شان چې ټکړې ټکړې کړے شوى وى او د هغې يوه ټوټه به هم دومره نۀ وى چې په هغې کښې بل سکارۀ راواخستلے شى، يا په کښې د ډيګۍ نه اوبۀ راوويستلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17121, 'Isaiah 30:15', 'Isaiah', 30, 15, '&nbsp;قادر مطلق خُدائ د بنى اِسرائيلو مقدس ذات، فرمائى، ”راواپس شئ او په ما پوره يقين کوئ. نو بيا به تاسو تکړه او محفوظ يئ.“ خو تاسو داسې نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17122, 'Isaiah 30:16', 'Isaiah', 30, 16, '&nbsp;خو ستاسو منصوبه دا ده چې په تېزو آسونو باندې سوارۀ شئ او د خپل دشمن نه وتښتئ. تاسو صحيح يئ، ځکه چې تاسو به تښتئ. ستاسو خيال دا دے چې ستاسو آسونه ښۀ تېزه منډه وهلے شى، خو چې څوک درپسې وى نو هغوئ به ستاسو نه تېز وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17123, 'Isaiah 30:17', 'Isaiah', 30, 17, '&nbsp;کۀ ستاسو د دشمن يو فوجى دهمکى درکړى نو ستاسو زر کسان به منډې وهى، او کۀ پينځۀ سپاهيان دهمکى درکړى نو دا به ستاسو ټولو زغلولو دپاره کافى وى. او کۀ په آخر کښې څوک پاتې شى نو هغوئ به د غرۀ په سر باندې د جنډې د يو لرګى په شان يواځې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17124, 'Isaiah 30:18', 'Isaiah', 30, 18, '&nbsp;خو مالِک خُدائ بيا هم په دې انتظار کښې دے چې په تاسو باندې رحم وکړى. هغه په تاسو باندې د رحم کولو دپاره تيار دے ځکه چې هغه وفادار خُدائ پاک دے. بختور دى هغوئ چې د هغۀ د مدد په انتظار کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17125, 'Isaiah 30:19', 'Isaiah', 30, 19, '&nbsp;اے د يروشلم خلقو تاسو به نور نۀ ژاړئ. کله چې تاسو هغۀ ته د مدد دپاره فرياد وکړئ، نو هغه به خامخا په تاسو رحم وکړى او چې څنګه ستاسو دُعاګانې واورى نو جواب به درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17126, 'Isaiah 30:20', 'Isaiah', 30, 20, '&nbsp;اګر چې مالِک خُدائ به تاسو ته د تنګ لاس روټۍ او د تکليف اوبۀ درکړى، خو هغه به په خپله ستاسو اُستاذ وى او تاسو ته به نور د هغۀ د لټولو ضرورت نۀ پېښيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17127, 'Isaiah 30:21', 'Isaiah', 30, 21, '&nbsp;کۀ تاسو د لارې نه ښى يا ګس طرف ته واوړئ، نو د وروستو نه به ستاسو لار ښودنه کيږى چې، ”دا لاره صحيح ده، په دې روان شئ.“ تاسو به په خپلو غوږونو دا اورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17128, 'Isaiah 30:22', 'Isaiah', 30, 22, '&nbsp;نو بيا به تاسو خپل هغه بُتان چې په سرو زرو پټ وى او هغه بُتان چې په سپينو زرو پټ وى هغه به واخلئ او وايئ به چې، ”دا څۀ ګند دے.“ او بهر په ډيران به يې ګزار کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17129, 'Isaiah 30:23', 'Isaiah', 30, 23, '&nbsp;کله چې تاسو تخم وکَرئ، نو مالِک خُدائ به د دې شين کېدو دپاره باران راولېږى او د دې نه به تاسو ته ښۀ او زيات پېداوار مِلاو شى او ستاسو د څاروو دپاره به د څرن ښۀ ډېره زمکه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17130, 'Isaiah 30:24', 'Isaiah', 30, 24, '&nbsp;کوم غوَيى او خرونه چې ستاسو په پټو کښې يوې کوى نو هغه به هم هغه خوراک کوى چې چج او درې غاښۍ سره صفا شوے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17131, 'Isaiah 30:25', 'Isaiah', 30, 25, '&nbsp;په هغه ورځ کله چې ستاسو د دشمن قلعې قبضه شى او د هغوئ خلق ووژلے شى، نو د هر غرۀ نه او د هرې غونډۍ نه به د اوبو وَلې رابهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17132, 'Isaiah 30:26', 'Isaiah', 30, 26, '&nbsp;سپوږمۍ به د نمر په شان ځليږى او نمر به په اووۀ چنده زيات روښانه شى، دا به داسې وى لکه چې د اوو ورځو رڼا يو ځائ شى. دا به په هغه وخت کښې وشى کله چې مالِک خُدائ د خپلو خلقو د هغه زخمونو مرهم پټۍ وکړى او هغه زخمونه ورله روغ کړى چې کوم زخمونه هغۀ ورکړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17133, 'Isaiah 30:27', 'Isaiah', 30, 27, '&nbsp;وګورئ د مالِک خُدائ نوم د لرې ځائ نه راروان دے. هغه لوئ غضب او رُعب داب سره رانزدې کيږى. د هغۀ شونډې د غصې نه ريږدى، او د هغۀ وينا لکه د اور هر څۀ ايرې ايرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17134, 'Isaiah 30:28', 'Isaiah', 30, 28, '&nbsp;د هغۀ ساه لکه د سېلاب په شان ده چې هر څۀ تر مرۍ مرۍ ډوبوى. هغه به مغروره قومونه د تباهۍ دپاره چاڼ کړى. هغه به دوئ قابو کړى او د بربادۍ په طرف به يې يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17135, 'Isaiah 30:29', 'Isaiah', 30, 29, '&nbsp;خو اے د خُدائ پاک خلقو، تاسو به خوشحاله يئ او داسې سندرې به وايئ لکه څنګه سندرې چې د مقدس اختر په شپه وئيلے شى. تاسو به د هغه خلقو په شان خوشحاله يئ کوم چې د مالِک خُدائ کور ته د شپېلۍ د ساز سره روان وى، چې هغه د بنى اِسرائيلو حِفاظت کوونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17136, 'Isaiah 30:30', 'Isaiah', 30, 30, '&nbsp;مالِک خُدائ به په هر يو کس باندې خپل پُرجلاله آواز واورى او د خپلې غصې زور به ورته وښائى. هلته به د اور لمبې، تندر، ږلۍ او دروند باران وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17137, 'Isaiah 30:31', 'Isaiah', 30, 31, '&nbsp;کله چې اسوريان د مالِک خُدائ آواز واورى او د هغۀ د سزا پته ورته ولګى نو هغوئ به ويريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17138, 'Isaiah 30:32', 'Isaiah', 30, 32, '&nbsp;کله چې مالِک خُدائ هغوئ بار بار ووهى، نو د هغۀ خلق به هر ځلې د منګى او بينجو ساز ورسره غږوى. خُدائ پاک به پخپله د اسوريانو خِلاف جنګ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17139, 'Isaiah 30:33', 'Isaiah', 30, 33, '&nbsp;ډېره موده مخکښې يو ځائ تيار شوے وو چرته به چې يو لوئ اور د اسور بادشاه سوزوى. د لرګو يو اوچت ډېرے به وى. مالِک خُدائ به د نِهر په شان د سوزېدونکو ګوګړو يوه لمبه پو کړى او دې له به اور ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17140, 'Isaiah 31:1', 'Isaiah', 31, 1, '&nbsp;کوم خلق چې د مدد غوښتلو دپاره مِصر ته ځى نو په هغوئ باندې افسوس. ځکه چې هغوئ د مِصر په لوئ فوجى طاقت، آسونو، جنګى ګاډو او فوجيانو باندې بهروسه کوى. خو هغوئ په مالِک خُدائ باندې يقين نۀ کوى، کوم چې د بنى اِسرائيلو مقدس ذات دے او نۀ ترې نه مدد غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17141, 'Isaiah 31:2', 'Isaiah', 31, 2, '&nbsp;خو مالِک خُدائ پاک هم هوښيار دے. هغه په تاسو افت راولى. هغه خپلې خبرې سر ته رسوى چې بدعمله او هغه خلقو له سزا ورکړى چې څوک د دې بدعمله خلقو حِفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17142, 'Isaiah 31:3', 'Isaiah', 31, 3, '&nbsp;مِصريان خو څۀ خُدايان نۀ دى، هغوئ خو بنى آدم دى. د هغوئ آسونه خو څۀ آسمانى مخلوق نۀ دے ځکه چې دا آسونه د غوښې نه جوړ دى. کله چې مالِک خُدائ خپل لاس اوږد کړى، نو څوک چې د چا مدد کوى نو هغه به راپرېوځى او د چا چې مدد کيږى نو هغه به هم راپرېوځى او دا دواړه به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17143, 'Isaiah 31:4', 'Isaiah', 31, 4, '&nbsp;مالِک خُدائ ما ته وفرمائيل، ”کۀ د شپانو ډلې هر څومره چغې ووهى يا هر څومره آوازونه وکړى، خو هغوئ به يو غړمبېدونکى ازمرى د خپل ښکار نه ونۀ شړى، نو هم دغه شان به مالِک خُدائ ربُ الافواج د صيون په غر راکوز شى او جنګ به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17144, 'Isaiah 31:5', 'Isaiah', 31, 5, '&nbsp;لکه څنګه چې يو مارغۀ د خپلو بچو د بچ کولو دپاره د خپلې جالې دپاسه الوځى رالوځى، نو داسې به زۀ، مالِک خُدائ، ربُ الافواج د يروشلم دپاسه تېر شم د دې د بچ کولو دپاره او د دې حِفاظت به کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17145, 'Isaiah 31:6', 'Isaiah', 31, 6, '&nbsp;مالِک خُدائ وفرمائيل، ”اے بنى اِسرائيلو، تاسو زما خِلاف سرکشى کړې ده. خو اوس، تاسو ما ته راوګرځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17146, 'Isaiah 31:7', 'Isaiah', 31, 7, '&nbsp;يو داسې ورځ راروانه ده چې تاسو ټول به د سرو زرو او سپينو زرو نه جوړ شوى بُتان غورزوئ کوم چې تاسو په خپلو ګناهګارو لاسونو جوړ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17147, 'Isaiah 31:8', 'Isaiah', 31, 8, '&nbsp;اسوريان به په تُوره تباه شى خو دا تُوره به د انسان نۀ وى. د خُدائ پاک تُوره به هغوئ ووهى او هغوئ به وارخطا شى او تښتى به. د اسوريانو ځوانانو نه به په زور کار اخستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17148, 'Isaiah 31:9', 'Isaiah', 31, 9, '&nbsp;د يرې د وجې به هغوئ خپله قلعه پرېږدى، او د هغوئ آفسران به د مالِک خُدائ د جنګى جنډې نه ويريږى.“ دا مالِک خُدائ فرمائيلى دى، د چا اور چې په صيون کښې بليږى، او د چا تنور چې په يروشلم ګرميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17149, 'Isaiah 32:1', 'Isaiah', 32, 1, '&nbsp;ګورئ، يو بادشاه به په اِنصاف سره حکمرانى کوى. او د هغۀ آفسران به هم په اِنصاف سره حکمرانى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17150, 'Isaiah 32:2', 'Isaiah', 32, 2, '&nbsp;د بادشاه هر يو کس به د سيلۍ نه د حِفاظت، او د طوفان نه د پټېدو د ځائ په شان وى. هغوئ به د داسې نِهر په شان وى چې په صحرا کښې بهيږى او هغوئ به په خُشک مُلک کښې د لوئ ګټ د سورى په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17151, 'Isaiah 32:3', 'Isaiah', 32, 3, '&nbsp;نو بيا چې د چا سترګې وى نو هغوئ به حقيقت وينى، او چې د چا غوږونه وى نو هغوئ به د اورېدو جوګه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17152, 'Isaiah 32:4', 'Isaiah', 32, 4, '&nbsp;څوک چې د بې‌صبرۍ نه کار اخلى هغوئ به هوښيار شى، او چاړاګان به صفا او روانۍ سره خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17153, 'Isaiah 32:5', 'Isaiah', 32, 5, '&nbsp;څوک به دا نۀ وائى چې کم عقل کس عزتمند وى او يا بدعمله کس نېک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17154, 'Isaiah 32:6', 'Isaiah', 32, 6, '&nbsp;يو کم عقل کس د کم عقلتوب خبرې کوى او د بدعملۍ کولو منصوبې جوړوى. هغه د بې‌دينۍ خبرې کوى او د مالِک خُدائ خلاف کُفر غروى. هيڅکله اوږو خلقو له خوراک نۀ ورکوى او تږى د څۀ څښلو نه محرومه ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17155, 'Isaiah 32:7', 'Isaiah', 32, 7, '&nbsp;کم عقل انسان بدعمله وى او د بدعملۍ کارونه کوى، هغه د دروغو سره د غريب د تباه کېدو منصوبې جوړوى اګر کۀ حاجتمند په حقه هم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17156, 'Isaiah 32:8', 'Isaiah', 32, 8, '&nbsp;خو عزتمند انسان د صداقت کار کوى او چې کوم کار صحيح وى نو په هغې باندې کلک ولاړ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17157, 'Isaiah 32:9', 'Isaiah', 32, 9, '&nbsp;اے هغه ښځو، څوک چې په آرام سره ژوند تېروئ زما خبره واورئ. اے بې‌پرواه لوڼو زما خبره په غور سره واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17158, 'Isaiah 32:10', 'Isaiah', 32, 10, '&nbsp;يو کال او څو ورځې پس به تاسو بې‌پرواه ښځې په لړزان شئ، ځکه چې د انګورو فصل به ضائع شى او مېوې به هيڅکله نۀ پخيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17159, 'Isaiah 32:11', 'Isaiah', 32, 11, '&nbsp;اے هغه ښځو، څوک چې په آرام سره ژوند تېروئ، د يرې نه ولړزېږئ. اے بې‌غمه لوڼو د يرې نه ورپېږئ. خپلې کپړې وباسئ بربنډې شئ او د ټاټ جامې واچوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17160, 'Isaiah 32:12', 'Isaiah', 32, 12, '&nbsp;د زرخېزه پټو او د انګورو باغونو دپاره د خفګان نه خپلې سينې وهئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17161, 'Isaiah 32:13', 'Isaiah', 32, 13, '&nbsp;زما د خلقو په مُلک کښې د ازغو او غنو بوټى راشنۀ شوى دى. ستاسو د کورونو خندا او د ښارونو خوشحالى به ختمه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17162, 'Isaiah 32:14', 'Isaiah', 32, 14, '&nbsp;محل به خوشے پاتې شى او مرکزى ښار به خالى شى. د کورونو او قلعو نه به د تل دپاره کنډرات جوړ شى، چرته به چې ځنګلى خرونه ګرځى او ګډې به په کښې څريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17163, 'Isaiah 32:15', 'Isaiah', 32, 15, '&nbsp;ترڅو چې خُدائ پاک خپل روح په مونږ نازل نۀ کړى نو تر هغه وخته پورې به حالات هم داسې وى. خو بيا به هغه خوشے مُلک آباد شى او د باغ مېوه دارې ونې به يې لکه د ځنګل په شان ګڼې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17164, 'Isaiah 32:16', 'Isaiah', 32, 16, '&nbsp;نو بيا به اِنصاف په صحرا کښې استوګنه کوى، او صداقت به په مېوه دار باغ کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17165, 'Isaiah 32:17', 'Isaiah', 32, 17, '&nbsp;د صداقت اثر به سلامتى وى، او نتيجه به يې ابدى سکون او حفاظت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17166, 'Isaiah 32:18', 'Isaiah', 32, 18, '&nbsp;زما خلق به پُرسکون او محفوظ ځايونو کښې اوسيږى، او د هغوئ کورونه به د امن او سلامتۍ نه ډک وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17167, 'Isaiah 32:19', 'Isaiah', 32, 19, '&nbsp;اګر کۀ ځنګل تباه شى او ښار مکمل برباد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17168, 'Isaiah 32:20', 'Isaiah', 32, 20, '&nbsp;خو بختور يئ تاسو چې د ټولو اوبو په غاړه به فصلونه وکرلے شئ او په آزادۍ سره به خپل خرونه او څاروى وڅرولے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17169, 'Isaiah 33:1', 'Isaiah', 33, 1, '&nbsp;په تاسو اسوريانو باندې افسوس، تاسو نور خو برباد کړل خو پخپله هيڅکله برباد نۀ شوئ. په تاسو باندې افسوس چې تاسو نورو سره دوکه وکړه حالانکه تاسو سره دوکه نۀ ده شوې. خو ستاسو نمبر به هم راځى. کله چې تاسو تباهى وکړئ نو تاسو به هم تباه شئ. کله چې تاسو د دوکې کار سر ته ورسوئ نو تاسو سره به هم دوکه وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17170, 'Isaiah 33:2', 'Isaiah', 33, 2, '&nbsp;اے مالِکه خُدايه، په مونږ رحم وکړه، مونږ ستا په طمع يُو. هر سحر مونږ له طاقت راکوه. او د مصيبت په وخت کښې زمونږ خلاصونکے شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17171, 'Isaiah 33:3', 'Isaiah', 33, 3, '&nbsp;ستا د تندر په شان آواز اورېدو سره قومونه زغلى، ستا پاڅېدو سره هغوئ خوارۀ وارۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17172, 'Isaiah 33:4', 'Isaiah', 33, 4, '&nbsp;ستا د لوټ مال دومره راجمع شى لکه چې ډېر چينجى راجمع شوى وى، او خلق په مالِ غنيمت باندې لکه د قحطۍ د مُولخانو ټوپونه وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17173, 'Isaiah 33:5', 'Isaiah', 33, 5, '&nbsp;زمونږ مالِک خُدائ څومره لوئ دے. هغه پاس په عرش استوګنه کوى. هغه به يروشلم د اِنصاف او صداقت نه ډک کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17174, 'Isaiah 33:6', 'Isaiah', 33, 6, '&nbsp;په هغه ورځ به هغه ستاسو مضبوط بنياد وى، هغه به تاسو له لوئ خلاصون، پوهه او حِکمت درکوى. د مالِک خُدائ يره به ستاسو خزانه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17175, 'Isaiah 33:7', 'Isaiah', 33, 7, '&nbsp;خو اوس تکړه خلق په لارو کوڅو کښې ژړاګانې کوى. کومو سفيرانو چې د امن راوستلو کوشش کولو نو اوس هغوئ په چغو چغو ژاړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17176, 'Isaiah 33:8', 'Isaiah', 33, 8, '&nbsp;هغه سړکونه خوشې تشې پاتې دى او هيڅ څوک هم پرې سفر نۀ کوى. معاهدې ماتې شوې دى او په لوظُونو باندې عمل نۀ دے شوے. نور د يو کس عزت هم نۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17177, 'Isaiah 33:9', 'Isaiah', 33, 9, '&nbsp;مُلک خوشے او وران ويجاړ پروت دے. د لبنان ځنګلونه اوچ شوى دى او د شارون آباده وادى د صحرا په شان ده او د بسن او د کرمل د غرۀ د ونو نه پاڼې غورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17178, 'Isaiah 33:10', 'Isaiah', 33, 10, '&nbsp;نو مالِک خُدائ فرمائى، ”اوس به زۀ عملى کار کوم. زۀ به تاسو ته وښايم چې زۀ څومره طاقتور يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17179, 'Isaiah 33:11', 'Isaiah', 33, 11, '&nbsp;تاسو اُميد سره يئ خو ستاسو په خېټه کښې اوچه ګياه ده او د پېدايښت په وخت به درنه صرف بوس پېدا کيږى. چې کله تاسو پوکے وهئ نو ستاسو ساه نه به اور جوړ شى او تاسو به ايرې ايرې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17180, 'Isaiah 33:12', 'Isaiah', 33, 12, '&nbsp;قومونه به په مکمل طور داسې وسوزى، لکه د ازغو د هغه بوټو په شان چې کټ کړے شى او اور ته وغورزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17181, 'Isaiah 33:13', 'Isaiah', 33, 13, '&nbsp;اے هغه د لرې علاقو خلقو هغې ته غوږ کېږدئ څۀ چې ما کړى دى، او اے نزدې اوسېدونکو زما طاقت ومنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17182, 'Isaiah 33:14', 'Isaiah', 33, 14, '&nbsp;د صيون ګناهګار خلق د يرې نه ريږدى. بې‌دينه خلق رپيږى او وائى، ”د خُدائ پاک تباه کوونکى اور په وړاندې څوک ژوندى پاتې کېدے شى؟ زمونږ د خلقو نه به څوک په داسې ابدى اور کښې ژوندى پاتې شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17183, 'Isaiah 33:15', 'Isaiah', 33, 15, '&nbsp;خو هغه کس به ژوندے پاتې شى چې صداقت سره ژوند تېروى او رښتينے وى، غېر قانونى ګټه او رشوت نۀ اخلى، چې د قتل منصوبې نۀ جوړوى او د غلطو کارونو نه ځان ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17184, 'Isaiah 33:16', 'Isaiah', 33, 16, '&nbsp;نو بيا به دا خلق په اوچتو ځايونو کښې اوسيږى، هغوئ به دومره محفوظ وى لکه څومره چې په غرونو باندې پَخو قلعو کښې محفوظ وى. هغوئ ته به روټۍ ملاويږى او د اوبو به هيڅ کمے نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17185, 'Isaiah 33:17', 'Isaiah', 33, 17, '&nbsp;تاسو به وګورئ بادشاه به د شان او شوکت سره په يو داسې مُلک باندې حکومت کوى چې تر لرې لرې پورې خور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17186, 'Isaiah 33:18', 'Isaiah', 33, 18, '&nbsp;بيا به تاسو د يرې دا تېر وخت راياد کړئ او خپل ځان سره به ووايئ، ”د دشمن هغه لوئ آفسران چرته دى؟ محصُول اخستونکى چرته غېب شول؟ هغه آفسر چرته دے چې د برجونو حساب کِتاب به يې کولو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17187, 'Isaiah 33:19', 'Isaiah', 33, 19, '&nbsp;نو تاسو به نور د پردى مُلک هغه ظالمان ونۀ وينئ چې هغوئ داسې سخته ژبه وائى چې په هغې باندې تاسو نۀ پوهېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17188, 'Isaiah 33:20', 'Isaiah', 33, 20, '&nbsp;صيون ته وګورئ، دا هغه ښار دے چرته چې مونږ مذهبى اخترونه کوُو. يروشلم ته وګورئ، دا به د اوسېدو دپاره څومره محفوظ ځائ وى. دا به يو داسې خېمه وى چې هيڅکله به نۀ شى اخوا کولے، د دې موږى به کله هم نۀ راويستلے کيږى، او د دې پړى به هيڅکله نۀ شليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17189, 'Isaiah 33:21', 'Isaiah', 33, 21, '&nbsp;هلته به مالِک خُدائ زمونږ لوئ بادشاه وى. هغه به لکه د حفاظت د لوئ سمندر په شان وى چې يو دشمن به هم ترېنه نۀ شى اوړېدے او نۀ به پرې د دشمن سمندرى جهازُونه ګرځېدے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17190, 'Isaiah 33:22', 'Isaiah', 33, 22, '&nbsp;مالِک خُدائ به په خپله زمونږ قاضى، زمونږ حکمران، او زمونږ بادشاه وى، هغه به زمونږ خيال ساتى او مونږ به بچ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17191, 'Isaiah 33:23', 'Isaiah', 33, 23, '&nbsp;د سمندرى جهاز پړى ډيله دى، او د بادبان ستن يې خوَزى او بادبان يې خور شوے نۀ دے. مونږ به د خپلو دشمنانو ټول د لوټ مال دولت تقسيم کړُو او دا به دومره زيات وى چې ګوډ ته به هم په کښې خپله برخه مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17192, 'Isaiah 33:24', 'Isaiah', 33, 24, '&nbsp;د صيون يو کس به هم بيا نۀ وائى چې، ”مونږ بيمار يُو،“ او مالِک خُدائ به د هغوئ ګناهونه معاف کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17193, 'Isaiah 34:1', 'Isaiah', 34, 1, '&nbsp;اے د ټولو قومونو خلقو، راشئ. راغونډ شئ او واورئ. په ټوله دُنيا کښې چې څوک هم اوسيږى نو هغه دې دلته راشى او وا دې ورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17194, 'Isaiah 34:2', 'Isaiah', 34, 2, '&nbsp;مالِک خُدائ ټولو قومونو او د هغوئ ټولو لښکرو ته غصه دے او هغه به دوئ په مکمل طور تباه کړى او ذبح به يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17195, 'Isaiah 34:3', 'Isaiah', 34, 3, '&nbsp;خو د هغوئ لاشونه به نۀ ښخيږى او هلته به پراتۀ وى چې سخا شى او خراب بوئ وکړى، او غرونه به په وينو سرۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17196, 'Isaiah 34:4', 'Isaiah', 34, 4, '&nbsp;په آسمان کښې ستورى به فنا شى. آسمان به داسې فنا شى لکه چې طومار راغونډولے شى او ستورى به داسې راوغورزيږى لکه د انګورو د بوټى نه اوچې پاڼې يا د اينځر د ونې نه اوچ اينځر راغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17197, 'Isaiah 34:5', 'Isaiah', 34, 5, '&nbsp;او زما تُورې خپل کار په آسمان کښې پوره کړے دے، او ګورئ اوس به دا په ادوم نازله شى، په هغه قوم کوم چې ما د تباهۍ دپاره په نښه کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17198, 'Isaiah 34:6', 'Isaiah', 34, 6, '&nbsp;د مالِک خُدائ تُوره په وينه او وازګه باندې پټه شوې ده، دا د ګډورو او د چېلو په وينو سره ده او وازګې ورباندې لګېدلې دى، ولې چې مالِک خُدائ به دا قربانى د بُصره په ښار کښې پېش کړى، هغه به دا لويه حلاله د ادوم په مُلک کښې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17199, 'Isaiah 34:7', 'Isaiah', 34, 7, '&nbsp;خلق به د ځنګلى غوَيى او د سخو په شان راوغورزيږى او زمکه به په وينه سره وى او په وازګه به پټه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17200, 'Isaiah 34:8', 'Isaiah', 34, 8, '&nbsp;دا هغه ورځ ده چې مالِک خُدائ به بدل واخلى، هغه کال چې د ادوم نه به د بنى اِسرائيلو بدله واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');